<div class="narrow wide-form"><a class="back-link" href="<?= e(url('rooms')) ?>"><?= icon('chevron-left') ?>Voltar para Salas</a><section class="card card-body"><h2><?= e($title) ?></h2><p class="muted">Preencha os dados do ambiente. Campos com * são obrigatórios.</p><?php form_errors($errors); ?><form class="stacked-form" method="post" action="<?= e(url('rooms',['action'=>!empty($record['id'])?'update':'store']+(!empty($record['id'])?['id'=>$record['id']]:[]))) ?>"><?= csrf_field() ?><?php field('name','Nome da sala',$record,$errors,'text',true,120); ?><div class="form-grid"><?php select_field('type','Tipo',options_for(\App\Models\Room::TYPES),$record,$errors);field('capacity','Capacidade',$record,$errors,'number');field('floor','Andar',$record,$errors,'text',true,60);select_field('status','Status',options_for(\App\Models\Room::STATUSES),$record+['status'=>'Disponível'],$errors); ?></div><?php field('features','Recursos (separados por vírgula)',$record,$errors,'text',true,500);field('description','Descrição',$record,$errors,'textarea',true,3000);select_field('image','Imagem do ambiente',['scene-1.jpg'=>'Laboratório','scene-2.jpg'=>'Biblioteca','scene-3.jpg'=>'Auditório','scene-4.jpg'=>'Informática','scene-5.jpg'=>'Sala de Aula','scene-6.jpg'=>'Sala de Reuniões'],$record+['image'=>'scene-5.jpg'],$errors); ?><div class="form-actions"><a class="button button-outline" href="<?= e(url('rooms')) ?>">Cancelar</a><button class="button"><?= icon('check') ?>Salvar sala</button></div></form></section></div>
